export function canAdvance(completedTaskIds: string[], task: WorkflowTask): boolean {
  return task.dependsOn.every((id) => completedTaskIds.includes(id));
}

export function isBlockingGrade(grade: Grade): boolean {
  return grade === 'C' || grade === 'BLOCK';
}

export function mergeAllowed(grades: Grade[], humanWaiver = false): boolean {
  if (humanWaiver) return true;
  return grades.length > 0 && grades.every((grade) => grade === 'A' || grade === 'B');
}

